  name: "stub-status-text",
  setup(b) {
    b.onLoad({ filter: /status-text\.ts$/ }, () => ({
      contents: "export function getReasonPhrase(){return undefined}",
      loader: "ts",
    }));
  },
};

async function size(code, plugins) {
  const res = await build({
    bundle: true,
    metafile: true,
    write: false,
    minify: true,
    format: "esm",
    platform: "node",
    outfile: "index.mjs",
    treeShaking: true,
    conditions: ["browser"],
    logOverride: { "ignored-bare-import": "silent" },
    plugins,
    stdin: {
      contents: code,
      resolveDir: "C:/dev/runs/ra9a9d993df/test/bench",
      sourcefile: "index.mjs",
      loader: "js",
    },
  });
  return {
    bytes: res.metafile.outputs["index.mjs"].bytes,
    gzip: zlib.gzipSync(res.outputFiles[0].text).byteLength,
  };
}

for (const [name, code] of Object.entries(entries)) {
  console.log("current", name, JSON.stringify(await size(code, [])));
  console.log("stubTable", name, JSON.stringify(await size(code, [stubStatusText])));
}

